            int blockScoped = 42;
            System.out.println("Inside if-block: blockScoped = " + blockScoped);
        }

        int outerAccumulator = 0;
        for (int i = 1; i <= 3; i++) {
            int loopIterationScoped = i * 10;
            outerAccumulator += loopIterationScoped;
