import java.util.concurrent.atomic.AtomicInteger;

public class Solution {
    public static void main(String[] args) {
        int factor = 5; // Effectively final
        AtomicInteger counter = new AtomicInteger(0);
        int[] arrayBox = new int[1];

        Runnable task = () -> {
            // factor cannot be modified here, but counter and arrayBox references are final
            counter.addAndGet(factor);
            arrayBox[0] += factor;
        };

        task.run();
        task.run();

        System.out.println("AtomicInteger value: " + counter.get());
        System.out.println("Array box value: " + arrayBox[0]);
    }
}

