public class Solution {
    public static int factorial(int n) {
        int currentN = n; // Local to this invocation's stack frame
        System.out.println("Entering frame: n = " + currentN);
        if (n <= 1) {
            System.out.println("Base case reached: returning 1");
            return 1;
        }
        int result = n * factorial(n - 1);
        System.out.println("Exiting frame: n = " + currentN + ", returned = " + result);
        return result;
    }

    public static void main(String[] args) {
        int finalResult = factorial(3);
        System.out.println("Final Factorial(3): " + finalResult);
    }
}

