import java.util.ArrayDeque;
import java.util.Deque;
import java.util.HashMap;
import java.util.Map;

public class Solution {
    static class SymbolTable {
        private final Deque<Map<String, String>> scopes = new ArrayDeque<>();

        public SymbolTable() {
            enterScope(); // Global scope
        }

        public void enterScope() {
            scopes.push(new HashMap<>());
        }

        public void exitScope() {
            if (scopes.size() > 1) {
                scopes.pop();
            }
        }

        public void declare(String name, String type) {
            scopes.peek().put(name, type);
        }

        public String lookup(String name) {
            for (Map<String, String> scope : scopes) {
                if (scope.containsKey(name)) {
                    return scope.get(name);
                }
            }
            return null;
        }
    }

    public static void main(String[] args) {
        SymbolTable table = new SymbolTable();
        table.declare("globalVar", "int");

        table.enterScope(); // Enter block
        table.declare("localVar", "String");
        System.out.println("Inside block - localVar: " + table.lookup("localVar"));
        System.out.println("Inside block - globalVar: " + table.lookup("globalVar"));

        table.exitScope(); // Exit block
        System.out.println("After block - localVar: " + table.lookup("localVar"));
        System.out.println("After block - globalVar: " + table.lookup("globalVar"));
    }
}

public class Solution {
    static class TransactionContext {
        private static final ThreadLocal<String> currentTransaction = new ThreadLocal<>();

        public static void setTransaction(String id) {
            currentTransaction.set(id);
        }

        public static String getTransaction() {
            return currentTransaction.get();
        }

        public static void clear() {
            currentTransaction.remove();
        }
    }

    public static void main(String[] args) throws InterruptedException {
        Thread t1 = new Thread(() -> {
            try {
                TransactionContext.setTransaction("TXN-1001");
                System.out.println("Thread 1 context: " + TransactionContext.getTransaction());
            } finally {
                TransactionContext.clear();
            }
        });

        Thread t2 = new Thread(() -> {
            try {
                TransactionContext.setTransaction("TXN-2002");
                System.out.println("Thread 2 context: " + TransactionContext.getTransaction());
            } finally {
                TransactionContext.clear();
            }
        });

        t1.start();
        t1.join();
        t2.start();
        t2.join();

        System.out.println("Main thread context: " + TransactionContext.getTransaction());
    }
}
